import type { NormalizedTx, PortfolioSnapshot, RiskAnalysis } from "@/types";
import { formatAmount, formatPct, formatUsd } from "@/lib/utils/format";

/**
 * Rule-based template answers — NO model is involved. Used when live NEAR AI
 * inference is unavailable (not configured, no credits, or disabled for demo
 * visitors). Every statement is computed from the data passed in, so the
 * same templates are accurate for sample data and for a user's live data.
 * The UI labels them "Template response — not generated by NEAR AI" and they
 * are never marked as verified.
 */

export interface TemplateInput {
  portfolio: PortfolioSnapshot;
  risk: RiskAnalysis | null;
  transactions?: NormalizedTx[] | null;
  /** Why live inference was unavailable — shown in the footnote. */
  reason: string;
}

export function templateAnswer(question: string, input: TemplateInput): string {
  const { portfolio: p, risk: r } = input;
  const q = question.toLowerCase();
  const live = p.provenance.mode === "live";
  const scope = live ? "your live data" : "sample data";
  const cat = (id: string) => r?.categories.find((c) => c.id === id);
  const note = `\n\n> _Template response computed from ${scope} — **not produced by NEAR AI**. ${input.reason}_`;
  const end = `\n\nThis is not financial advice.${note}`;

  if (p.holdings.length === 0) {
    return `## No portfolio data yet\n\nAdd a NEAR wallet on the dashboard so there is data to analyse.${note}`;
  }

  if (/risk|report/.test(q) && r) {
    const drivers = [...r.categories]
      .filter((c) => c.score !== null)
      .sort((a, b) => (b.score ?? 0) * b.weight - (a.score ?? 0) * a.weight)
      .slice(0, 2);
    const flagged = r.categories.filter((c) => (c.id === "suspicious" || c.id === "activity") && (c.score ?? 0) >= 30);
    return `## Risk overview (${scope})

**Facts**
- Overall risk score: **${r.overallScore === null ? "n/a" : Math.round(r.overallScore)} / 100** (${r.level}).
${r.categories.map((c) => `- ${c.label}: ${c.score === null ? "insufficient data" : Math.round(c.score)}`).join("\n")}

**Interpretation**
- ${drivers.length ? `The largest contributors are ${drivers.map((c) => c.label.toLowerCase()).join(" and ")}.` : "There is not enough data to rank risk drivers."}
${flagged.map((c) => `- ${c.label}: ${c.explanation}`).join("\n")}${end}`;
  }

  if (/concentrat|exposure|allocation/.test(q)) {
    const top = p.allocation[0];
    const conc = cat("concentration");
    return `## Concentration (${scope})

**Facts**
- ${top ? `${top.symbol} represents **${formatPct(top.pct, { digits: 1 })}** of priced value.` : "No priced assets."}
- Allocation: ${p.allocation.map((a) => `${a.symbol} ${formatPct(a.pct, { digits: 1 })}`).join(", ") || "—"}.
${conc && conc.score !== null ? `- Concentration score: ${Math.round(conc.score)} / 100 — ${conc.explanation}` : ""}

**Interpretation**
- ${top && top.pct > 50 ? "A single-asset drawdown would dominate portfolio outcomes. Consider whether that matches your risk tolerance." : "No single asset dominates the priced portfolio."}${end}`;
  }

  if (/perform|poor|worst|loss|gain|best/.test(q)) {
    const withChange = p.holdings.filter((h) => h.change24hPct !== null);
    const worst = [...withChange].sort((a, b) => (a.change24hPct ?? 0) - (b.change24hPct ?? 0))[0];
    const best = [...withChange].sort((a, b) => (b.change24hPct ?? 0) - (a.change24hPct ?? 0))[0];
    const perf = cat("performance");
    return `## Performance (${scope})

**Facts**
- Portfolio 24h change: ${formatPct(p.change24hPct, { sign: true })} (${formatUsd(p.change24hUsd)}).
${worst ? `- Weakest 24h performer: **${worst.symbol}** at ${formatPct(worst.change24hPct, { sign: true })}.` : "- No 24h price-change data available."}
${best && best !== worst ? `- Strongest 24h performer: **${best.symbol}** at ${formatPct(best.change24hPct, { sign: true })}.` : ""}
${perf ? `- ${perf.explanation}` : ""}

**Interpretation**
- Short-term moves are noisy; review whether each position still matches your thesis.${end}`;
  }

  if (/transact|trade|behavio|activity|recent/.test(q)) {
    const txs = input.transactions ?? [];
    if (txs.length === 0) return `## Recent activity (${scope})\n\nNo recent transactions are available to summarise.${note}`;
    const failed = txs.filter((t) => t.success === false).length;
    const out = txs.filter((t) => t.direction === "out").reduce((s, t) => s + t.depositNear, 0);
    const inn = txs.filter((t) => t.direction === "in").reduce((s, t) => s + t.depositNear, 0);
    const calls = new Map<string, number>();
    for (const t of txs) for (const a of t.actions) if (a.kind === "FUNCTION_CALL") calls.set(t.receiver, (calls.get(t.receiver) ?? 0) + 1);
    const topCalls = [...calls.entries()].sort((a, b) => b[1] - a[1]).slice(0, 3);
    return `## Recent activity (${scope})

**Facts**
- ${txs.length} recent transaction(s) between ${txs[txs.length - 1].timestamp.slice(0, 10)} and ${txs[0].timestamp.slice(0, 10)}.
- NEAR sent: ${formatAmount(out)} · NEAR received: ${formatAmount(inn)}.
- Failed transactions: ${failed}.
${topCalls.length ? `- Most-called contracts: ${topCalls.map(([c, n]) => `\`${c}\` (${n})`).join(", ")}.` : "- No contract calls in the sample."}

**Interpretation**
- ${failed > 0 ? "Review failed transactions you do not recognise — failed calls to unknown contracts are a common phishing pattern." : "No failed transactions in the sample."}${end}`;
  }

  return `## Portfolio snapshot (${scope})

**Facts**
- Total priced value: **${formatUsd(p.totalValueUsd)}** across ${p.wallets.length} wallet(s).
- 24h change: ${formatPct(p.change24hPct, { sign: true })}.
- Allocation: ${p.allocation.map((a) => `${a.symbol} ${formatPct(a.pct, { digits: 1 })}`).join(", ") || "—"}.
- ${p.unpricedAssets} unpriced asset(s) excluded from totals.
${r && r.overallScore !== null ? `- Risk score: ${Math.round(r.overallScore)} / 100 (${r.level}).` : ""}

**Interpretation**
- Ask about risks, concentration, performance or recent transactions for a focused breakdown.${end}`;
}

/** Back-compat wrapper for demo sessions. */
export function demoAnswer(question: string, p: PortfolioSnapshot, r: RiskAnalysis, reason = "Live AI analysis is temporarily unavailable."): string {
  return templateAnswer(question, { portfolio: p, risk: r, reason });
}
